const input = $input.all();
const htmlText = typeof input[0].json.data === 'string' ? input[0].json.data : JSON.stringify(input[0].json);

const wh = $('Webhook: Start HTTP Scrape').first().json;
const platform = ((wh.body && wh.body.platform) || wh.platform || 'unknown').toLowerCase();
const bookUrl = (wh.body && wh.body.book_page_url) || wh.book_page_url || '';
const startChapter = parseInt((wh.body && wh.body.start_chapter) || wh.start_chapter || 1);
const endChapter = (wh.body && wh.body.end_chapter) || wh.end_chapter || null;
const batchSize = parseInt((wh.body && wh.body.batch_size) || wh.batch_size || 100);

function firstMatch(html, patterns) {
  for (const re of patterns) {
    const m = html.match(re);
    if (m && m[1]) return m[1].replace(/<[^>]+>/g, '').trim();
  }
  return '';
}

function decodeHTML(str) {
  return (str || '')
    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&nbsp;/g, ' ')
    .replace(/&#(\d+);/g, (m, n) => String.fromCharCode(parseInt(n)));
}

function extractLinks(html, pattern) {
  const results = [];
  const re = new RegExp(pattern.source || pattern, 'gi');
  let m;
  while ((m = re.exec(html)) !== null) {
    results.push({ href: m[1], text: (m[2] || '').replace(/<[^>]+>/g, '').trim() });
  }
  return results;
}

let meta = { book_name: '', author: '', description: '', cover_url: '', chapter_count: 0, _needs_ajax: false, _ajax_chapter_list: null };
let chapterLinks = [];
let baseUrl = '';

if (platform === 'webnovel') {
  baseUrl = 'https://www.webnovel.com';
  const bookIdM = bookUrl.match(/\/book\/(\d+)/);
  const bookId = bookIdM ? bookIdM[1] : null;

  // Try SSR data embedded in page
  const ssrM = htmlText.match(/window\.__SSR_DATA__\s*=\s*(\{[\s\S]+?\});\s*<\/script>/);
  if (ssrM) {
    try {
      const ssrData = JSON.parse(ssrM[1]);
      const bookInfo = ssrData.book || ssrData.bookInfo || {};
      meta.book_name = bookInfo.bookName || bookInfo.title || '';
      const authors = bookInfo.authorItems || [];
      meta.author = authors.length > 0 ? authors.map(a => a.name).join(', ') : (bookInfo.authorName || '');
      const items = bookInfo.chapterItems || ssrData.chapterItems || [];
      if (bookId) {
        chapterLinks = items.map(ch => ({
          href: baseUrl + '/book/' + bookId + '/chapter/' + ch.id,
          text: ch.name || ch.chapterName || '',
        }));
      }
    } catch(e) {}
  }

  // Fallback: chapterItems JSON in page
  if (chapterLinks.length === 0) {
    const jsonM = htmlText.match(/"chapterItems"\s*:\s*(\[[\s\S]*?\])\s*[,}]/);
    if (jsonM && bookId) {
      try {
        const items = JSON.parse(jsonM[1]);
        chapterLinks = items.map(ch => ({
          href: baseUrl + '/book/' + bookId + '/chapter/' + ch.id,
          text: ch.name || ch.chapterName || '',
        }));
      } catch(e) {}
    }
  }

  // Fallback: fetch catalog page via ajax path
  if (chapterLinks.length === 0 && bookId) {
    meta._ajax_chapter_list = baseUrl + '/book/' + bookId + '/catalog';
    meta._needs_ajax = true;
  }

  if (!meta.book_name) {
    meta.book_name = decodeHTML(firstMatch(htmlText, [
      /"bookName":"([^"]+)"/i,
      /<h1[^>]*>([^<]+)<\/h1>/i,
    ]));
  }
  if (!meta.author) {
    meta.author = decodeHTML(firstMatch(htmlText, [
      /"authorName":"([^"]+)"/i,
      /class="[^"]*author[^"]*"[^>]*>[^<]*<a[^>]*>([^<]+)/i,
    ]));
  }
}

if (platform === 'novelbin') {
  baseUrl = 'https://novelbin.com';
  meta.book_name = decodeHTML(firstMatch(htmlText, [
    /<h3[^>]*class="[^"]*title[^"]*"[^>]*>([^<]+)/i,
    /<h3[^>]*class="[^"]*truyen-title[^"]*"[^>]*>([^<]+)/i,
  ]));
  meta.author = decodeHTML(firstMatch(htmlText, [
    /class="[^"]*author[^"]*"[^>]*>\s*<[^>]+>([^<]+)/i,
  ]));
  chapterLinks = extractLinks(htmlText,
    /href="(https?:\/\/novelbin\.com\/b\/[^"]+\/chapter[^"]+)"[^>]*>([^<]*(?:Chapter|Chap|Ch)[^<]*)/i
  );
  if (chapterLinks.length === 0) {
    const idMatch = bookUrl.match(/\/b\/([^/]+)/);
    if (idMatch) {
      meta._ajax_chapter_list = 'https://novelbin.com/ajax/chapter-archive?novelId=' + idMatch[1];
      meta._needs_ajax = true;
    }
  }
}

if (platform === 'freewebnovel') {
  baseUrl = 'https://freewebnovel.com';
  meta.book_name = decodeHTML(firstMatch(htmlText, [
    /<h1[^>]*class="[^"]*tit[^"]*"[^>]*>([^<]+)/i,
    /<h1[^>]*>([^<]+)<\/h1>/i,
  ]));
  meta.author = decodeHTML(firstMatch(htmlText, [
    /class="[^"]*author[^"]*"[^>]*>[^<]*<a[^>]*>([^<]+)/i,
  ]));
  chapterLinks = extractLinks(htmlText,
    /href="(\/chapter\/[^"]+)"[^>]*>([^<]*(?:Chapter|Chap)[^<]*)/i
  ).map(l => ({ ...l, href: baseUrl + l.href }));
}

if (platform === 'royalroad') {
  baseUrl = 'https://www.royalroad.com';
  meta.book_name = decodeHTML(firstMatch(htmlText, [
    /<h1[^>]*class="[^"]*font-white[^"]*"[^>]*>([^<]+)/i,
    /<h1[^>]*>([^<]+)<\/h1>/i,
  ]));
  // Try JSON-LD structured data first
  const ldM = htmlText.match(/<script[^>]*type="application\/ld\+json"[^>]*>([\s\S]*?)<\/script>/i);
  if (ldM) {
    try {
      const ld = JSON.parse(ldM[1]);
      if (ld.author && ld.author.name) meta.author = ld.author.name;
      else if (Array.isArray(ld.author) && ld.author[0]) meta.author = ld.author[0].name || '';
    } catch(e) {}
  }
  if (!meta.author) {
    meta.author = decodeHTML(firstMatch(htmlText, [
      /"author":\{[^}]*"name":"([^"]+)"/i,
      /<span[^>]*property="name"[^>]*>([^<]+)<\/span>/i,
      /class="[^"]*author[^"]*"[^>]*>[^<]*<a[^>]*>([^<]+)/i,
    ]));
  }
  const chRe = /href="(\/fiction\/\d+\/[^/"]+\/chapter\/\d+\/[^"]+)"/gi;
  const chSeen = new Set();
  let chM;
  while ((chM = chRe.exec(htmlText)) !== null) {
    const href = baseUrl + chM[1];
    if (!chSeen.has(href)) { chSeen.add(href); chapterLinks.push({ href, text: '' }); }
  }
}

if (platform === 'wattpad') {
  baseUrl = 'https://www.wattpad.com';
  meta.book_name = decodeHTML(firstMatch(htmlText, [
    /<h1[^>]*>([^<]+)<\/h1>/i,
    /class="[^"]*story-title[^"]*"[^>]*>([^<]+)/i,
  ]));
  chapterLinks = extractLinks(htmlText,
    /href="(\/[^"]*\/[^"]+)"[^>]*class="[^"]*part-title[^"]*"[^>]*>([^<]+)/i
  ).map(l => ({ ...l, href: baseUrl + l.href }));
}

const totalLinks = chapterLinks.length;
const sliced = chapterLinks.slice(Math.max(0, startChapter - 1), endChapter ? endChapter : chapterLinks.length);
const numberedChapters = sliced.map((ch, i) => ({
  chapter_num: startChapter + i,
  url: ch.href,
  title_hint: ch.text || ('Chapter ' + (startChapter + i)),
}));

const batches = [];
for (let i = 0; i < numberedChapters.length; i += batchSize) {
  const batch = numberedChapters.slice(i, i + batchSize);
  batches.push({
    batch_index: Math.floor(i / batchSize) + 1,
    chapter_start: batch[0].chapter_num,
    chapter_end: batch[batch.length - 1].chapter_num,
    chapters: batch,
  });
}

return [{ json: {
  status: 'ok',
  platform,
  book_url: bookUrl,
  book_name: meta.book_name || 'Unknown Title',
  author: meta.author || 'Unknown Author',
  chapter_count: totalLinks,
  scraped_range: startChapter + '\u2013' + (endChapter || totalLinks),
  total_chapters_to_scrape: numberedChapters.length,
  batch_size: batchSize,
  total_batches: batches.length,
  batches,
  _needs_ajax: meta._needs_ajax || false,
  _ajax_chapter_list: meta._ajax_chapter_list || null,
}}];

const ajaxHtml = $input.first().json.data || JSON.stringify($input.first().json) || '';
const prev = $('Code: Parse Book Metadata + Chapter List').first().json;

const startChapter = prev.scraped_range ? parseInt(prev.scraped_range) : 1;
const batchSize = prev.batch_size || 100;
const platform = prev.platform || 'unknown';
const bookUrl = prev.book_url || '';
const bookIdM = bookUrl.match(/\/book\/(\d+)/);
const bookId = bookIdM ? bookIdM[1] : '';

const links = [];

if (platform === 'webnovel') {
  // Try SSR data in catalog page
  const ssrM = ajaxHtml.match(/window\.__SSR_DATA__\s*=\s*(\{[\s\S]+?\});\s*<\/script>/);
  if (ssrM) {
    try {
      const ssrData = JSON.parse(ssrM[1]);
      const items = ssrData.chapterItems || (ssrData.book && ssrData.book.chapterItems) || [];
      for (const ch of items) {
        links.push({ href: 'https://www.webnovel.com/book/' + bookId + '/chapter/' + ch.id, text: ch.name || ch.chapterName || '' });
      }
    } catch(e) {}
  }
  // Fallback: JSON chapterItems in page
  if (links.length === 0) {
    const jsonM = ajaxHtml.match(/"chapterItems"\s*:\s*(\[[\s\S]*?\])\s*[,}]/);
    if (jsonM) {
      try {
        const items = JSON.parse(jsonM[1]);
        for (const ch of items) {
          links.push({ href: 'https://www.webnovel.com/book/' + bookId + '/chapter/' + ch.id, text: ch.name || '' });
        }
      } catch(e) {}
    }
  }
  // Fallback: href regex
  if (links.length === 0) {
    const re = /href="(\/book\/\d+\/[^"]+\/chapter\/\d+[^"]*)"/gi;
    const seen = new Set();
    let m;
    while ((m = re.exec(ajaxHtml)) !== null) {
      if (!seen.has(m[1])) { seen.add(m[1]); links.push({ href: 'https://www.webnovel.com' + m[1], text: '' }); }
    }
  }
} else if (platform === 'novelbin') {
  const re = /href="(https?:\/\/novelbin\.com\/b\/[^"]+\/chapter[^"]+)"[^>]*>([^<]*)/gi;
  let m;
  while ((m = re.exec(ajaxHtml)) !== null) {
    links.push({ href: m[1], text: m[2].trim() });
  }
} else {
  const re = /href="(https?:\/\/[^"]+\/chapter[^"]+)"[^>]*>([^<]*)/gi;
  let m;
  while ((m = re.exec(ajaxHtml)) !== null) {
    links.push({ href: m[1], text: m[2].trim() });
  }
}

const sliced = links.slice(startChapter - 1);
const numbered = sliced.map((ch, i) => ({
  chapter_num: startChapter + i,
  url: ch.href,
  title_hint: ch.text || ('Chapter ' + (startChapter + i)),
}));

const batches = [];
for (let i = 0; i < numbered.length; i += batchSize) {
  const batch = numbered.slice(i, i + batchSize);
  batches.push({
    batch_index: Math.floor(i / batchSize) + 1,
    chapter_start: batch[0].chapter_num,
    chapter_end: batch[batch.length - 1].chapter_num,
    chapters: batch,
  });
}

return [{ json: { ...prev, batches, total_batches: batches.length, chapter_count: links.length } }];

const data = $input.first().json;
const batches = data.batches || [];

if (batches.length === 0) {
  return [{ json: { status: 'error', error: 'No chapters found to scrape', ...data } }];
}

return batches.map(batch => ({ json: {
  book_name: data.book_name,
  author: data.author,
  platform: data.platform,
  book_url: data.book_url,
  batch_index: batch.batch_index,
  chapter_start: batch.chapter_start,
  chapter_end: batch.chapter_end,
  chapters: batch.chapters,
  total_batches: data.total_batches,
}}));

const batch = $input.first().json;
if (!batch.chapters || batch.chapters.length === 0) {
  return [{ json: { status: 'error', error: 'Batch has no chapters', ...batch } }];
}
return batch.chapters.map(ch => ({ json: {
  book_name: batch.book_name,
  author: batch.author,
  platform: batch.platform,
  book_url: batch.book_url,
  batch_index: batch.batch_index,
  chapter_start: batch.chapter_start,
  chapter_end: batch.chapter_end,
  total_batches: batch.total_batches,
  chapter_num: ch.chapter_num,
  chapter_url: ch.url,
  title_hint: ch.title_hint,
}}));

// Run once for ALL items — process every chapter HTTP response by index
const allItems = $input.all();
const allPrev = $('Code: Split Chapters in Batch').all();

function stripHtml(str) {
  return (str || '')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&nbsp;/g, ' ')
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(parseInt(n)))
    .replace(/\s+/g, ' ').trim();
}

function extractRRParagraphs(htmlStr) {
  const divIdx = htmlStr.search(/class="[^"]*chapter-content[^"]*"/i);
  const startPos = divIdx >= 0 ? htmlStr.indexOf('>', divIdx) + 1 : 0;
  const fromContent = htmlStr.slice(startPos);
  const paragraphs = [];
  const lc = fromContent.toLowerCase();
  let pos = 0;
  while (pos < lc.length) {
    const pOpen = lc.indexOf('<p', pos);
    if (pOpen < 0) break;
    const tagEnd = lc.indexOf('>', pOpen);
    if (tagEnd < 0) break;
    const pClose = lc.indexOf('</p>', tagEnd);
    const end = pClose >= 0 ? pClose : Math.min(tagEnd + 2000, lc.length);
    const raw = htmlStr.slice(tagEnd + 1, end);
    const text = stripHtml(raw).trim();
    if (text.length > 10) paragraphs.push(text);
    pos = pClose >= 0 ? pClose + 4 : tagEnd + 1;
  }
  return paragraphs;
}

function extractTagContent(html, openTag, closeTag) {
  const results = [];
  const lc = html.toLowerCase();
  const ct = closeTag.toLowerCase();
  let pos = 0;
  while (pos < lc.length) {
    const open = lc.indexOf(openTag, pos);
    if (open < 0) break;
    const tagEnd = lc.indexOf('>', open);
    if (tagEnd < 0) break;
    const close = lc.indexOf(ct, tagEnd);
    const end = close >= 0 ? close : tagEnd + 1;
    const raw = html.slice(tagEnd + 1, end);
    const text = stripHtml(raw).trim();
    if (text.length > 10) results.push(text);
    pos = close >= 0 ? close + ct.length : tagEnd + 1;
  }
  return results;
}

const results = [];

for (let i = 0; i < allItems.length; i++) {
  const httpResponse = allItems[i].json;
  const htmlStr = typeof httpResponse.data === 'string' ? httpResponse.data : JSON.stringify(httpResponse);
  const prev = (allPrev[i] || allPrev[0]).json || {};

  const platform = prev.platform || 'unknown';
  const chapterNum = prev.chapter_num || (i + 1);
  const titleHint = prev.title_hint || ('Chapter ' + chapterNum);

  let title = titleHint;
  let paragraphs = [];

  if (platform === 'royalroad') {
    const titleM = htmlStr.match(/<h1[^>]*>([^<]+)<\/h1>/i);
    if (titleM) title = stripHtml(titleM[1]);
    paragraphs = extractRRParagraphs(htmlStr);
  }

  if (platform === 'webnovel') {
    const ssrM = htmlStr.match(/window\.__SSR_DATA__\s*=\s*(\{[\s\S]+?\});\s*<\/script>/);
    if (ssrM) {
      try {
        const ssrData = JSON.parse(ssrM[1]);
        const ch = ssrData.chapter || ssrData.chapterInfo || {};
        title = ch.chapterName || ch.name || titleHint;
        const content = ch.content || ch.chapterContent || '';
        if (content) {
          const cleaned = content.replace(/<[^>]+>/g, '\n').replace(/&nbsp;/g, ' ');
          paragraphs = cleaned.split(/\n+/).map(p => p.trim()).filter(p => p.length > 10);
        }
      } catch(e) {}
    }
    if (paragraphs.length === 0) {
      const contentM = htmlStr.match(/"content":"((?:[^"\\]|\\.)*)"/)
      if (contentM) {
        const raw = contentM[1].replace(/\\n/g, '\n').replace(/\\t/g, ' ').replace(/\\"/g, '"');
        paragraphs = raw.split(/\n+/).filter(p => p.trim().length > 10);
      }
    }
    const titleM = htmlStr.match(/"chapterName":"([^"]+)"/);
    if (titleM && title === titleHint) title = titleM[1];
  }

  if (platform === 'novelbin') {
    const titleM = htmlStr.match(/<span[^>]*class="[^"]*chr-text[^"]*"[^>]*>([^<]+)/i) || htmlStr.match(/<h2[^>]*>([^<]+)<\/h2>/i);
    if (titleM) title = stripHtml(titleM[1]);
    paragraphs = extractTagContent(htmlStr, '<div', '</div>').filter(p => p.length > 30);
    if (paragraphs.length === 0) paragraphs = extractTagContent(htmlStr, '<p', '</p>').filter(p => p.length > 20);
  }

  if (platform === 'freewebnovel') {
    const titleM = htmlStr.match(/<h1[^>]*>([^<]+)<\/h1>/i);
    if (titleM) title = stripHtml(titleM[1]);
    paragraphs = extractTagContent(htmlStr, '<p', '</p>').filter(p => p.length > 20);
  }

  if (platform === 'wattpad') {
    const titleM = htmlStr.match(/<h2[^>]*>([^<]+)<\/h2>/i);
    if (titleM) title = stripHtml(titleM[1]);
    paragraphs = extractTagContent(htmlStr, '<p', '</p>').filter(p => p.length > 20);
  }

  if (paragraphs.length === 0) {
    paragraphs = extractTagContent(htmlStr, '<p', '</p>').filter(p => p.length > 40);
  }

  const seen = new Set();
  const cleaned = paragraphs.filter(p => {
    const key = p.slice(0, 60);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });

  const wordCount = cleaned.join(' ').split(/\s+/).filter(w => w).length;

  results.push({ json: {
    book_name: prev.book_name,
    author: prev.author,
    platform: prev.platform,
    batch_index: prev.batch_index,
    chapter_start: prev.chapter_start,
    chapter_end: prev.chapter_end,
    total_batches: prev.total_batches,
    chapter_num: chapterNum,
    chapter_url: prev.chapter_url,
    title,
    paragraphs: cleaned,
    word_count: wordCount,
    is_empty: cleaned.length === 0,
  }});
}

return results;

const chapters = $input.first().json.data || [];
if (!chapters.length) return [{ json: { status: 'error', error: 'No chapters aggregated' } }];

const first = chapters[0];
const bookName = first.book_name || 'Unknown Book';
const author = first.author || 'Unknown Author';
const batchIndex = first.batch_index || 1;
const chapterStart = first.chapter_start;
const chapterEnd = first.chapter_end;

chapters.sort((a, b) => (a.chapter_num || 0) - (b.chapter_num || 0));

const lines = [];
lines.push(bookName);
lines.push('Author: ' + author);
lines.push('Chapters ' + chapterStart + '\u2013' + chapterEnd);
lines.push('');
lines.push('\u2500'.repeat(60));
lines.push('');

const chapterStats = [];
const emptyChapters = [];
const qcIssues = [];
let prevNum = chapterStart - 1;

for (const ch of chapters) {
  const num = ch.chapter_num;
  const title = ch.title || ch.title_hint || ('Chapter ' + num);
  const paras = ch.paragraphs || [];
  const wordCount = ch.word_count || 0;

  if (num !== prevNum + 1 && prevNum > 0) {
    qcIssues.push({ type: 'gap', from: prevNum, to: num, missing: num - prevNum - 1 });
  }
  prevNum = num;

  if (paras.length === 0) {
    emptyChapters.push(num);
    qcIssues.push({ type: 'empty', chapter: num, title });
  }

  lines.push('Chapter ' + num + ': ' + title);
  lines.push('');
  if (paras.length > 0) lines.push(...paras);
  else lines.push('[EMPTY CHAPTER — No content extracted]');
  lines.push('');
  lines.push('\u2500'.repeat(40));
  lines.push('');

  chapterStats.push({ chapter: num, title, word_count: wordCount });
}

const totalWords = chapterStats.reduce((s, c) => s + c.word_count, 0);
lines.push('');
lines.push('='.repeat(60));
lines.push('WORD COUNT SUMMARY');
lines.push('='.repeat(60));
for (const s of chapterStats) {
  lines.push('Chapter ' + s.chapter + ': ' + s.title.slice(0, 40) + ' \u2014 ' + s.word_count.toLocaleString() + ' words');
}
lines.push('');
lines.push('Total: ' + totalWords.toLocaleString() + ' words across ' + chapterStats.length + ' chapter(s)');
if (emptyChapters.length > 0) lines.push('Empty chapters: ' + emptyChapters.join(', '));

const docTitle = bookName + ' \u2014 Ch' + chapterStart + '-' + chapterEnd;
const content = lines.join('\n');

return [{ json: {
  status: 'ok',
  doc_title: docTitle,
  book_name: bookName,
  author,
  chapter_start: chapterStart,
  chapter_end: chapterEnd,
  batch_index: batchIndex,
  total_batches: first.total_batches,
  total_words: totalWords,
  chapter_count: chapters.length,
  empty_chapters: emptyChapters,
  qc_issues: qcIssues,
  qc_passed: qcIssues.length === 0,
  content,
  doc_filename: bookName + ' Ch' + chapterStart + '-' + chapterEnd + '.txt',
}}];
